CREATE TABLE public.account_data (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, payload jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.account_data TO authenticated; GRANT ALL ON public.account_data TO service_role;
ALTER TABLE public.account_data ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own account data" ON public.account_data FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE TABLE public.billing_accounts (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, environment text NOT NULL CHECK (environment IN ('sandbox','live')), customer_id text, trial_used boolean NOT NULL DEFAULT false, checkout_session_id text, checkout_lock_until timestamptz, deleting boolean NOT NULL DEFAULT false, PRIMARY KEY(user_id,environment), UNIQUE(customer_id,environment));
GRANT SELECT ON public.billing_accounts TO authenticated; GRANT ALL ON public.billing_accounts TO service_role;
ALTER TABLE public.billing_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own billing account" ON public.billing_accounts FOR SELECT TO authenticated USING (auth.uid()=user_id);
CREATE TABLE public.generation_usage (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, environment text NOT NULL CHECK (environment IN ('sandbox','live')), last_success_at timestamptz, reservation_id uuid, reserved_until timestamptz, PRIMARY KEY(user_id,environment));
GRANT SELECT ON public.generation_usage TO authenticated; GRANT ALL ON public.generation_usage TO service_role;
ALTER TABLE public.generation_usage ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own usage" ON public.generation_usage FOR SELECT TO authenticated USING (auth.uid()=user_id);
CREATE TABLE public.payment_events (id text PRIMARY KEY, environment text NOT NULL CHECK(environment IN ('sandbox','live')), processed_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.payment_events TO service_role;
ALTER TABLE public.payment_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.subscriptions ADD COLUMN IF NOT EXISTS ended_at timestamptz;
COMMENT ON COLUMN public.profiles.is_premium IS 'DEPRECATED: entitlement is derived exclusively from webhook-written subscriptions';
CREATE OR REPLACE FUNCTION public.protect_profile_entitlement() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') OR coalesce(auth.role(),'') IN ('authenticated','anon') THEN IF (TG_OP='INSERT' AND NEW.is_premium=true) OR (TG_OP='UPDATE' AND NEW.is_premium IS DISTINCT FROM OLD.is_premium) THEN RAISE EXCEPTION 'Subscription entitlement is read-only'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_profile_entitlement BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_entitlement();
CREATE OR REPLACE FUNCTION public.reserve_generation(p_user uuid,p_env text,p_reservation uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.generation_usage; premium boolean; BEGIN IF p_env NOT IN ('sandbox','live') THEN RAISE EXCEPTION 'Invalid environment'; END IF; IF EXISTS(SELECT 1 FROM public.billing_accounts WHERE user_id=p_user AND environment=p_env AND deleting) THEN RAISE EXCEPTION 'Account deletion in progress'; END IF;
SELECT EXISTS(SELECT 1 FROM public.subscriptions WHERE user_id=p_user AND environment=p_env AND price_id IN ('pro_monthly','pro_yearly') AND ended_at IS NULL AND ((status IN ('active','trialing','past_due') AND (current_period_end IS NULL OR current_period_end>now())) OR (status='canceled' AND current_period_end>now()))) INTO premium;
INSERT INTO public.generation_usage(user_id,environment) VALUES(p_user,p_env) ON CONFLICT DO NOTHING;
SELECT * INTO r FROM public.generation_usage WHERE user_id=p_user AND environment=p_env FOR UPDATE;
IF r.reserved_until>now() THEN RETURN jsonb_build_object('allowed',false,'reason','in_progress'); END IF;
IF NOT premium AND r.last_success_at + interval '72 hours'>now() THEN RETURN jsonb_build_object('allowed',false,'next_at',r.last_success_at+interval '72 hours'); END IF;
UPDATE public.generation_usage SET reservation_id=p_reservation,reserved_until=now()+interval '5 minutes' WHERE user_id=p_user AND environment=p_env;
RETURN jsonb_build_object('allowed',true,'premium',premium); END $$;
REVOKE ALL ON FUNCTION public.reserve_generation(uuid,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reserve_generation(uuid,text,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.finish_generation(p_user uuid,p_env text,p_reservation uuid,p_success boolean,p_premium boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.generation_usage SET last_success_at=CASE WHEN p_success AND NOT p_premium THEN now() ELSE last_success_at END,reservation_id=NULL,reserved_until=NULL WHERE user_id=p_user AND environment=p_env AND reservation_id=p_reservation; END $$;
REVOKE ALL ON FUNCTION public.finish_generation(uuid,text,uuid,boolean,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finish_generation(uuid,text,uuid,boolean,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.lock_checkout(p_user uuid,p_env text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.billing_accounts(user_id,environment) VALUES(p_user,p_env) ON CONFLICT DO NOTHING; UPDATE public.billing_accounts SET checkout_lock_until=now()+interval '1 minute' WHERE user_id=p_user AND environment=p_env AND NOT deleting AND (checkout_lock_until IS NULL OR checkout_lock_until<now()); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.lock_checkout(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.lock_checkout(uuid,text) TO service_role;